function FolioChargeReversal({records,session,disabled,command}:{records:BusinessRecord[];session:WebSession;disabled:boolean;command:CommandFn}){
 const folios=active(records,'folios');const entries=active(records,'folioEntries');const [folioId,setFolioId]=useState(folios[0]?.id||'');const [entryId,setEntryId]=useState('');const [reason,setReason]=useState('');const [busy,setBusy]=useState(false);const [notice,setNotice]=useState('');
 const folioLabel=(folio:BusinessRecord)=>{const booking=active(records,'roomReservations').find(r=>r.id===folio.id);return `${name(active(records,'customers').find(r=>r.id===data(booking)?.customerId))} / Room ${name(active(records,'rooms').find(r=>r.id===data(booking)?.roomId))}`;};
 const charges=entries.filter(entry=>data(entry)?.folioId===folioId&&data(entry)?.kind==='CHARGE'&&!entries.some(other=>data(other)?.kind==='REVERSAL'&&(data(other)?.reversesEntryId||(data(other)?.details as Record<string,unknown>|undefined)?.reversesEntryId)===entry.id));
 const selected=charges.find(entry=>entry.id===entryId),selectedFolio=folios.find(row=>row.id===folioId),roomChargeOrderId=String((data(selected)?.details as Record<string,unknown>|undefined)?.orderId||''),roomChargeOrder=records.find(row=>row.collection==='orders'&&row.id===roomChargeOrderId);
 const reverse=async()=>{if(!selected||!selectedFolio||!reason.trim()||disabled||!allowed(session,'folio.reverse'))return;if(data(selected)?.sourceType==='POS'&&!roomChargeOrder){setNotice('Synchronize the linked POS order and review it before reversing this room charge.');return}setBusy(true);setNotice('');try{const expectedVersions=[{collection:'folios',id:selectedFolio.id,version:selectedFolio.version},{collection:'folioEntries',id:selected.id,version:selected.version},...(data(selected)?.sourceType==='POS'&&roomChargeOrder?[{collection:'orders',id:roomChargeOrder.id,version:roomChargeOrder.version}]:[])];const outcome=await command('folio.reverse','folios',folioId,{id:folioId,entryId:selected.id,reason:reason.trim(),expectedVersions});setNotice(outcomeMessage(outcome,'Folio charge reversal'));if(isCommandConfirmed(outcome)){setEntryId('');setReason('')}}catch(error){setNotice(error instanceof Error?error.message:'The reversal outcome could not be checked. Review Activity before retrying.')}finally{setBusy(false)}};
 return <section className="rounded-2xl border border-rose-700/30 bg-rose-950/10 p-4" aria-label="Reverse an unpaid folio charge"><h3 className="font-bold">Reverse an unpaid folio charge</h3><BlockerCard title="Reversal limits">Only an unreversed charge still represented in the guest's outstanding balance can be reversed. Paid charges require the separate refund workflow.</BlockerCard>{notice&&<p role="status" className="mt-3 rounded-lg border border-slate-700 p-3 text-sm">{notice}</p>}<div className="mt-3 grid gap-3 md:grid-cols-3"><FormField label="Guest folio"><select className={field} value={folioId} onChange={event=>{setFolioId(event.target.value);setEntryId('')}}><option value="">Select folio</option>{folios.filter(folio=>data(folio)?.status==='OPEN').map(folio=><option key={folio.id} value={folio.id}>{folioLabel(folio)} · balance {money(data(folio)?.balanceMinor)}</option>)}</select></FormField><FormField label="Charge"><select className={field} value={entryId} onChange={event=>setEntryId(event.target.value)}><option value="">Select an unreversed charge</option>{charges.map(entry=><option key={entry.id} value={entry.id}>{String(data(entry)?.description||data(entry)?.sourceType||'Folio charge')} · {money(data(entry)?.grossMinor)}</option>)}</select></FormField><FormField label="Reason" hint="Required for the audit record"><textarea className={field} value={reason} maxLength={1000} onChange={event=>setReason(event.target.value)} placeholder="Explain the correction"/></FormField></div><BusyButton busy={busy} disabled={disabled||!allowed(session,'folio.reverse')||!selected||!reason.trim()} className="mt-3" onClick={()=>void reverse()}>Review and reverse charge</BusyButton></section>;
}

export function WebHousekeepingView({records,session,disabled,command,client,queue=[],onActivity,onRefresh}:{records:BusinessRecord[];session:WebSession;disabled:boolean;command:CommandFn;client:ApiClient;queue?:QueuedCommand[];onActivity?:()=>void;onRefresh?:()=>Promise<void>}){
 const rooms=active(records,'rooms');const reservations=active(records,'roomReservations');const blocks=active(records,'roomBlocks');const [query,setQuery]=useState('');const [notice,setNotice]=useState('');
 const [holdReview,setHoldReview]=useState<{id:string;room:BusinessRecord;block?:BusinessRecord}|null>(null),[holdRoomId,setHoldRoomId]=useState('');
 const [assignmentRoomId,setAssignmentRoomId]=useState('');
 const timeZone=String(data(active(records,'hospitalitySettings')[0])?.timeZone||session.propertyContext?.timeZone||'Africa/Nairobi');const [reportRoom,setReportRoom]=useState<BusinessRecord|null>(null);const [reportDescription,setReportDescription]=useState('');const [reportPriority,setReportPriority]=useState('MEDIUM');const [actionBusy,setActionBusy]=useState(false);
 const visible=rooms.filter(record=>`${name(record)} ${data(record)?.floor||''} ${data(record)?.wing||''}`.toLowerCase().includes(query.toLowerCase()));
 const transition=(record:BusinessRecord,state:string)=>void run('room.housekeeping','rooms',record.id,{id:record.id,state});
 const run=async(operation:string,collection:string,id:string,payload:Record<string,unknown>):Promise<CommandOutcome>=>{setNotice('');try{const outcome=await command(operation,collection,id,payload);setNotice(outcomeMessage(outcome,'Housekeeping action'));return outcome}catch{const blocked:CommandOutcome={kind:'BLOCKED',message:'The Housekeeping action could not be confirmed. Check connectivity and permissions, then review Activity before retrying.'};setNotice(blocked.message);return blocked}};
 const condition=(record:BusinessRecord)=>{if(data(record)?.maintenanceState==='OUT_OF_SERVICE')void run('maintenance.returnToService','rooms',record.id,{id:record.id,expectedVersions:[{collection:'rooms',id:record.id,version:record.version}]});else{setReportDescription('');setReportPriority('MEDIUM');setReportRoom(record);}};
 const pendingRoomIds=useMemo(()=>new Set(active(records,'rooms').filter(room=>pendingRoomUpdate(records,queue,room.id)).map(room=>room.id)),[records,queue]);
 const roomPending=(room:BusinessRecord)=>pendingRoomIds.has(room.id);
 const createHold=(room:BusinessRecord)=>{if(disabled||actionBusy||roomPending(room)||!allowed(session,'rooms.manage'))return;setHoldReview({id:crypto.randomUUID(),room:{...room,data:{...room.data}}});};
 const releaseHold=(block:BusinessRecord)=>{const room=rooms.find(row=>row.id===block.data.roomId);if(disabled||actionBusy||!room||roomPending(room)||!allowed(session,'rooms.manage')||block.data.status!=='ACTIVE'||block.data.blockKind!=='OPERATING'||block.data.workOrderId)return;setHoldReview({id:block.id,room:{...room,data:{...room.data}},block:{...block,data:{...block.data}}});};
 const confirmReport=async(event:React.FormEvent)=>{event.preventDefault();if(!reportRoom||!reportDescription.trim()||disabled||!allowed(session,'maintenance.manage'))return;const id=crypto.randomUUID();setActionBusy(true);try{if(isCommandConfirmed(await run('maintenance.open','maintenanceWorkOrders',id,{id,roomId:reportRoom.id,title:`Room maintenance - ${reportPriority.toLowerCase()} priority`,fault:reportDescription.trim(),reason:reportDescription.trim(),expectedVersions:[{collection:'rooms',id:reportRoom.id,version:reportRoom.version}]}))){setReportRoom(null);setReportDescription('');setReportPriority('MEDIUM')}}finally{setActionBusy(false)}};
 const columns=['DIRTY','CLEANING','INSPECTED','READY'];const next:{[key:string]:string}={DIRTY:'CLEANING',CLEANING:'INSPECTED',INSPECTED:'READY'};
  return <section className="space-y-5" data-guide-anchor="web.housekeeping">
   <div className="flex flex-wrap items-start justify-between gap-3"><div><h2 className="flex items-center gap-2 text-2xl font-bold"><ClipboardCheck className="h-6 w-6 text-amber-300"/>Housekeeping</h2><p className="mt-1 text-sm text-slate-400">Room readiness is separate from occupancy. Transitions are versioned and audited.</p></div><label className="min-w-[240px] sm:max-w-sm"><span className="sr-only">Filter rooms</span><input className={field} placeholder="Filter room, floor, or wing" value={query} onChange={event=>setQuery(event.target.value)}/></label></div>
   {notice&&<p role="status" className="rounded-xl border border-slate-700 bg-slate-900 p-3 text-sm text-slate-300">{notice}</p>}
   <section className="space-y-3 rounded-2xl border border-amber-700/40 bg-slate-900 p-4" aria-label="Operating room holds">
    <div className="flex flex-wrap items-start justify-between gap-3"><div><h3 className="font-bold">Operating room holds</h3><p className="mt-1 text-sm text-slate-400">Current and future holds affect booking availability independently of cleanliness and serviceability. Releasing a hold does not mark a room clean or return it to service.</p></div>{allowed(session,'rooms.manage')&&<div className="flex flex-wrap gap-2"><label><span className="sr-only">Room for operating hold</span><select className={field} value={holdRoomId} disabled={disabled||actionBusy||Boolean(holdReview)} onChange={event=>setHoldRoomId(event.target.value)}><option value="">Choose a room</option>{rooms.map(room=><option key={room.id} value={room.id}>Room {name(room)}</option>)}</select></label><button type="button" className={button} disabled={disabled||actionBusy||Boolean(holdReview)||!rooms.some(room=>room.id===holdRoomId&&!roomPending(room))} onClick={()=>{const room=rooms.find(row=>row.id===holdRoomId);if(room)createHold(room);}}>Create operating hold</button></div>}</div>
    {blocks.filter(block=>block.data.status==='ACTIVE'&&block.data.blockKind==='OPERATING').map(block=>{const room=rooms.find(row=>row.id===block.data.roomId),starts=Date.parse(String(block.data.startsAt||'')),ends=Date.parse(String(block.data.endsAt||'')),intervalLabel=starts>Date.now()?'Future hold':ends<=Date.now()?'Interval ended; release not recorded':'Current hold';return <article key={block.id} className="rounded-xl border border-amber-700/30 bg-slate-950 p-3"><div className="flex flex-wrap items-start justify-between gap-3"><div><b>Room {name(room)} - {intervalLabel}</b><p className="mt-1 text-sm text-amber-200">{operationalText(block.data.reason,'Reason unavailable')}</p><p className="mt-1 text-xs text-slate-400">{date(block.data.startsAt,timeZone)} to {date(block.data.endsAt,timeZone)}</p><p className="mt-1 text-xs text-slate-400">Cleanliness: {String(room?.data.housekeepingState||'Unavailable')} / service: {String(room?.data.maintenanceState||'Unavailable')}</p>{room&&roomPending(room)&&<p role="status" className="mt-1 text-xs text-amber-200">Original room update awaits confirmation. Recover it in Activity.</p>}</div>{allowed(session,'rooms.manage')&&!block.data.workOrderId&&<button type="button" className={button} disabled={disabled||actionBusy||Boolean(holdReview)||!room||Boolean(room&&roomPending(room))} onClick={()=>releaseHold(block)}>Review and release hold</button>}</div></article>;})}
    {!blocks.some(block=>block.data.status==='ACTIVE'&&block.data.blockKind==='OPERATING')&&<p className="text-sm text-slate-400">No active operating holds in the synchronized room records.</p>}
   </section>
   <div className="grid gap-4 xl:grid-cols-4">{columns.map(state=><section key={state} className="min-w-0 rounded-2xl border border-slate-800 bg-slate-900 p-3"><div className="mb-3 flex items-center justify-between"><b>{state}</b><span className="rounded-full bg-slate-950 px-2 py-1 text-xs text-slate-500">{visible.filter(record=>(data(record)?.housekeepingState||'UNKNOWN')===state).length}</span></div><div className="space-y-2">{visible.filter(record=>(data(record)?.housekeepingState||'UNKNOWN')===state).map(record=><article key={record.id} className="rounded-xl bg-slate-950 p-3"><div className="flex justify-between gap-2"><div><b>Room {name(record)}</b><p className="mt-1 text-xs text-slate-400">Assigned: {operationalText(data(record)?.housekeepingAssignedName,'Unassigned')}</p></div>{data(record)?.maintenanceState==='OUT_OF_SERVICE'&&<ShieldAlert className="h-4 w-4 text-rose-300"/>}</div>{reservations.filter(reservation=>data(reservation)?.roomId===record.id&&['RESERVED','CHECKED_IN'].includes(String(data(reservation)?.status))).map(reservation=><p key={reservation.id} className="mt-2 text-xs text-sky-300">{String(data(reservation)?.status)} - departure {date(data(reservation)?.endsAt,timeZone)}</p>)}{blocks.filter(block=>data(block)?.roomId===record.id&&data(block)?.status==='ACTIVE').map(block=><div key={block.id} className="mt-2 rounded-lg border border-amber-800/30 p-2 text-xs text-amber-200"><b>{block.data.blockKind==='OPERATING'?'Operating hold':block.data.workOrderId||block.data.blockKind==='MAINTENANCE'?'Maintenance hold':'Hold origin unavailable'}</b><p>{operationalText(block.data.reason,'Reason unavailable')}</p><p>{date(block.data.startsAt,timeZone)} to {date(block.data.endsAt,timeZone)}</p>{block.data.blockKind!=='OPERATING'&&<p className="mt-1">{block.data.workOrderId||block.data.blockKind==='MAINTENANCE'?'Resolve the maintenance work order and inspection in Maintenance.':'Review its recorded evidence in Activity; generic release is unavailable.'}</p>}</div>)}{roomPending(record)&&<p role="status" className="mt-2 text-xs text-amber-200">Original room update pending. Review Activity before changing this room.</p>}<div className="mt-3 flex flex-wrap gap-2">{next[state]&&<button disabled={disabled||roomPending(record)||!allowed(session,'rooms.operate')} className={button} onClick={()=>transition(record,next[state])}>Advance</button>}{state==='INSPECTED'&&<button disabled={disabled||roomPending(record)||!allowed(session,'rooms.operate')} className={button} onClick={()=>transition(record,'DIRTY')}>Fail inspection</button>}{state==='READY'&&<button disabled={disabled||roomPending(record)||!allowed(session,'rooms.operate')} className={button} onClick={()=>transition(record,'DIRTY')}>Mark dirty</button>}<button disabled={disabled||roomPending(record)||!allowed(session,'maintenance.manage')} className={button} onClick={()=>condition(record)}>{data(record)?.maintenanceState==='OUT_OF_SERVICE'?'Return to service':'Out of order'}</button>{allowed(session,'rooms.manage')&&<button disabled={disabled||actionBusy||roomPending(record)} className={button} onClick={()=>setAssignmentRoomId(record.id)}>Assign housekeeping</button>}{allowed(session,'rooms.manage')&&<button disabled={disabled||actionBusy||Boolean(holdReview)||roomPending(record)} className={button} onClick={()=>createHold(record)}>Create operating hold</button>}{allowed(session,'maintenance.manage')&&<button disabled={disabled||roomPending(record)} className={button} onClick={()=>{setReportDescription('');setReportPriority('MEDIUM');setReportRoom(record)}}>Report maintenance</button>}</div></article>)}</div></section>)}</div>
   {assignmentRoomId&&rooms.find(room=>room.id===assignmentRoomId)&&<HousekeepingAssignmentDialog room={rooms.find(room=>room.id===assignmentRoomId)!} client={client} queue={queue} disabled={disabled} command={command} onClose={()=>setAssignmentRoomId('')}/>}
   {holdReview&&<OperatingRoomHoldDialog key={`${holdReview.block?'release':'create'}:${holdReview.id}`} review={holdReview} records={records} session={session} disabled={disabled} queue={queue} timeZone={timeZone} command={command} onActivity={onActivity} onRefresh={onRefresh} onClose={()=>setHoldReview(null)}/>}
   {reportRoom&&<Dialog title={`Report maintenance · ${name(reportRoom)}`} onClose={actionBusy?()=>undefined:()=>setReportRoom(null)} footer={<><button disabled={actionBusy} type="button" className={button} onClick={()=>setReportRoom(null)}>Cancel</button><button disabled={disabled||actionBusy||!allowed(session,'maintenance.manage')||!reportDescription.trim()} aria-busy={actionBusy} type="submit" form="room-maintenance-report-form" className={primary}>{actionBusy?'Reporting…':'Report problem'}</button></>}><form id="room-maintenance-report-form" className="space-y-3" onSubmit={event=>void confirmReport(event)}><p className="text-sm text-slate-400">This opens a maintenance work order and blocks the selected room until repair and inspection are recorded.</p><label className="block text-sm">What needs attention?<textarea required maxLength={4000} autoFocus className={`${field} mt-1`} value={reportDescription} onChange={event=>setReportDescription(event.target.value)}/></label><label className="block text-sm">Priority<select className={`${field} mt-1`} value={reportPriority} onChange={event=>setReportPriority(event.target.value)}><option value="LOW">Low</option><option value="MEDIUM">Normal</option><option value="HIGH">High</option><option value="CRITICAL">Critical</option></select></label></form></Dialog>}
  </section>;
}

function StayCard({record,guest,room,timeZone='Africa/Nairobi',children}:{record:BusinessRecord;guest:(id:string)=>string;room:(id:string)=>string;timeZone?:string;children:React.ReactNode}){return <article className="rounded-xl border border-slate-800 bg-slate-950 p-3"><div className="flex flex-wrap items-start justify-between gap-3"><div><b>{guest(String(data(record)?.customerId))}</b>{data(record)?.reservationNumber&&<p className="text-sm text-slate-300">{operationalText(data(record)?.reservationNumber,'Booking')}</p>}<p className="mt-1 text-sm text-slate-400">Room {room(String(data(record)?.roomId))} · {date(data(record)?.startsAt,timeZone)} – {date(data(record)?.endsAt,timeZone)}</p></div><div className="flex flex-wrap gap-2">{children}</div></div></article>}
function Queue({title,icon,children}:{title:string;icon:React.ReactNode;children:React.ReactNode}){return <section className="rounded-2xl border border-slate-800 bg-slate-900 p-4"><h3 className="mb-3 flex items-center gap-2 font-bold">{icon}{title}</h3><div className="space-y-2">{React.Children.count(children)?children:<p className="p-5 text-center text-sm text-slate-500">No matching stays.</p>}</div></section>}
function Metric({label,value}:{label:string;value:React.ReactNode}){return <div className="rounded-2xl border border-slate-800 bg-slate-900 p-4"><div className="text-xs text-slate-500">{label}</div><div className="mt-1 truncate text-xl font-black">{value}</div></div>}
function Empty({text}:{text:string}){return <p className="rounded-xl border border-dashed border-slate-700 p-5 text-center text-sm text-slate-500">{text}</p>}

/** Keep affected room actions held until durable outcomes and their returned projections agree. */
function pendingRoomUpdate(records:BusinessRecord[],queue:QueuedCommand[],roomId:string){
 return queue.find(entry=>{
  const payload=entry.command.payload;
  const affectsRoom=entry.command.expectedVersions.some(version=>version.collection==='rooms'&&version.id===roomId)||payload.roomId===roomId||entry.command.expectedVersions.some(version=>version.collection==='roomBlocks'&&records.some(record=>record.collection==='roomBlocks'&&record.id===version.id&&record.data.roomId===roomId));
  if(!affectsRoom)return false;
  if(entry.state==='PENDING_SYNC'||entry.state==='OUTCOME_UNKNOWN')return true;
  if(entry.state!=='SYNCHRONIZED')return false;
  return entry.result?.recordVersions.some(version=>['rooms','roomBlocks'].includes(version.collection)&&!records.some(record=>record.collection===version.collection&&record.id===version.id&&record.version>=version.version))===true;
 });
}

type OperatingHoldReview={id:string;room:BusinessRecord;block?:BusinessRecord};
type OperatingHoldAttempt={commandId:string;kind:'PENDING'|'UNKNOWN'|'CONFIRMED'|'TERMINAL'};
function OperatingRoomHoldDialog({review,records,session,disabled,queue,timeZone,command,onActivity,onRefresh,onClose}:{review:OperatingHoldReview;records:BusinessRecord[];session:WebSession;disabled:boolean;queue:QueuedCommand[];timeZone:string;command:CommandFn;onActivity?:()=>void;onRefresh?:()=>Promise<void>;onClose:()=>void}){
 const release=Boolean(review.block);
 const [reviewed,setReviewed]=useState(review),[starts,setStarts]=useState(()=>businessDateTimeInput(new Date(),timeZone)),[ends,setEnds]=useState(()=>businessDateTimeInput(new Date(Date.now()+86400000),timeZone)),[note,setNote]=useState('');
 const [busy,setBusy]=useState(false),[notice,setNotice]=useState(''),[needsReview,setNeedsReview]=useState(false),[attempt,setAttempt]=useState<OperatingHoldAttempt|null>(null);
 const latch=useRef(false),commandId=useRef(crypto.randomUUID()),latest=useRef({records,queue});latest.current={records,queue};
 const room=records.find(record=>record.collection==='rooms'&&record.id===review.room.id&&!record.archived),block=records.find(record=>record.collection==='roomBlocks'&&record.id===review.id&&!record.archived);
 const original=attempt?queue.find(entry=>entry.id===attempt.commandId):undefined;
 const pendingRoom=pendingRoomUpdate(records,queue,review.room.id);
 const held=Boolean(attempt&&attempt.kind!=='TERMINAL')||Boolean(pendingRoom);
 const changed=!room||room.version!==reviewed.room.version||release&&(!block||block.version!==reviewed.block?.version);
 const committed=Boolean(attempt&&room&&room.version>reviewed.room.version&&block&&block.data.blockKind==='OPERATING'&&(release?block.data.status==='RESOLVED'&&block.data.resolvedCommandId===attempt.commandId:block.data.sourceCommandId===attempt.commandId));
 let blocker='';
 if(!allowed(session,'rooms.manage'))blocker='Your staff account cannot create or release operating holds.';
 else if(!room)blocker='This room is unavailable. Review its current record in Activity.';
 else if(release&&(!block||block.data.blockKind!=='OPERATING'||block.data.workOrderId))blocker='Generic release is limited to operating holds. Maintenance and unknown-origin holds require their original workflow.';
 else if(release&&block?.data.status!=='ACTIVE')blocker='This hold is no longer active. Refresh and review its recorded outcome.';
 else if(!release&&block)blocker='This hold already has a server record. Inspect it in Activity instead of creating it again.';
 else if(!release&&room?.data.maintenanceState!=='AVAILABLE')blocker='Resolve maintenance and return the room to service before creating an operating hold.';
 else if(navigator.onLine===false)blocker='Reconnect to the business server before changing an operating hold. Offline changes are not bookings or confirmed holds.';
 else if(changed)blocker='The reviewed room or hold changed. Refresh and review the latest state before submitting.';
 else if(needsReview)blocker='The original action was not applied. Refresh and review before a new submission.';
 useEffect(()=>{
  if(!attempt)return;
  if((attempt.kind==='CONFIRMED'||original?.state==='SYNCHRONIZED')&&committed){onClose();return;}
  if(original?.state==='SYNCHRONIZED'&&attempt.kind!=='CONFIRMED'){setAttempt({...attempt,kind:'CONFIRMED'});setNotice('Confirmed by the server; waiting for the room and hold display to update. Do not submit again.');}
  else if(original&&['REJECTED','CONFLICT'].includes(original.state)&&attempt.kind!=='TERMINAL'){setAttempt({...attempt,kind:'TERMINAL'});setNeedsReview(true);setNotice(original.result?.error?.message||'The original hold action was not applied. Refresh and review before retrying.');}
 },[original?.state,original?.result?.error?.message,committed,attempt?.commandId,attempt?.kind,onClose]);
 const refreshReview=async()=>{
  if(latch.current||held)return;
  if(!onRefresh){setNeedsReview(true);setNotice('Use Activity to synchronize the original command and room records before reviewing another action.');return;}
  latch.current=true;setBusy(true);setNotice('');
  try{
   await onRefresh();
   const current=latest.current.records.find(record=>record.collection==='rooms'&&record.id===review.room.id&&!record.archived),currentBlock=latest.current.records.find(record=>record.collection==='roomBlocks'&&record.id===review.id&&!record.archived);
   if(!current||pendingRoomUpdate(latest.current.records,latest.current.queue,review.room.id)){setNeedsReview(true);setNotice('The room is unavailable or its original update is still pending. Recover it in Activity.');return;}
   if(release&&(!currentBlock||currentBlock.data.blockKind!=='OPERATING'||currentBlock.data.workOrderId||currentBlock.data.status!=='ACTIVE')){setNeedsReview(true);setNotice('The current block is not an active operating hold. Review its original evidence in Activity.');return;}
   if(!release&&currentBlock){setNeedsReview(true);setNotice('This hold is already recorded. Review the existing hold in Activity instead of submitting again.');return;}
   setReviewed({id:review.id,room:{...current,data:{...current.data}},...(currentBlock?{block:{...currentBlock,data:{...currentBlock.data}}}:{})});
   commandId.current=crypto.randomUUID();setAttempt(null);setNeedsReview(false);setNotice('Review the synchronized room, interval and note below before submitting a new command.');
  }catch{setNeedsReview(true);setNotice('The room records could not be synchronized. Reconnect and recover the original action in Activity before retrying.');}
  finally{latch.current=false;setBusy(false);}
 };
 const submit=async(event:React.FormEvent)=>{
  event.preventDefault();if(latch.current||disabled||held||blocker||note.trim().length<3||note.trim().length>1000)return;
  let startsAt='',endsAt='';
  if(/[\u0000-\u001f\u007f]/u.test(note.trim())){setNotice('Use a single plain-text reason without line breaks or control characters.');return;}
  if(!release)try{startsAt=businessDateTimeToUtc(starts,timeZone);endsAt=businessDateTimeToUtc(ends,timeZone);const start=Date.parse(startsAt),end=Date.parse(endsAt),now=Date.now(),year=366*86400000;if(!Number.isFinite(start)||!Number.isFinite(end)||end<=start||end<=now)throw new Error('Use a valid future interval with its end after its start.');if(start<now-300000||start>now+year||end-start>year)throw new Error('Refresh a start time more than five minutes old. Holds must start within 366 days and last no more than 366 days.');}catch(error){setNotice(error instanceof Error?error.message:'Review the operating hold interval.');return;}
  latch.current=true;setBusy(true);setNotice('');const submittedId=commandId.current;setAttempt({commandId:submittedId,kind:'PENDING'});
  try{
   const expectedVersions=[{collection:'rooms',id:reviewed.room.id,version:reviewed.room.version},{collection:'roomBlocks',id:review.id,version:release?reviewed.block!.version:0}];
   const outcome=await command(release?'room.unblock':'room.block','roomBlocks',review.id,{id:review.id,roomId:reviewed.room.id,reviewCommandId:submittedId,expectedVersions,...(release?{inspection:note.trim()}:{startsAt,endsAt,reason:note.trim()})});
   if(outcome.kind==='CONFIRMED'){setAttempt({commandId:outcome.commandId,kind:'CONFIRMED'});setNotice('Confirmed by the server; updating the room and hold display. Do not submit again.');}
   else if(outcome.kind==='PENDING'||outcome.kind==='OUTCOME_UNKNOWN'){setAttempt({commandId:outcome.commandId,kind:outcome.kind==='PENDING'?'PENDING':'UNKNOWN'});setNotice('The original hold action awaits confirmation. Recover the same command in Activity; do not create a replacement.');}
   else{setAttempt({commandId:'commandId' in outcome?outcome.commandId:submittedId,kind:'TERMINAL'});setNeedsReview(true);setNotice(outcome.kind==='DRAFT_SAVED'?'A draft was retained; the room availability has not changed. Review it in Activity and refresh before continuing.':outcome.message);}
  }catch{setAttempt({commandId:submittedId,kind:'UNKNOWN'});setNotice('The original hold action could not be checked. Recover it in Activity before submitting anything else for this room.');}
  finally{latch.current=false;setBusy(false);}
 };
 const locked=disabled||busy||held||Boolean(blocker);
 return <Dialog title={`${release?'Release operating hold':'Create operating hold'} - Room ${name(reviewed.room)}`} onClose={()=>{if(!latch.current&&!busy&&!held)onClose();}}>
  <form className="space-y-3" onSubmit={event=>void submit(event)}>
   <p className="text-sm text-slate-300">Cleanliness: {String(room?.data.housekeepingState||'Unavailable')} / service: {String(room?.data.maintenanceState||'Unavailable')}. {release?'This records only the release of this operating hold. It does not close maintenance work or mark the room ready.':'A server-confirmed operating hold reserves this interval from new bookings; it does not change cleanliness or repair status.'}</p>
   {release?<section className="rounded-xl border border-slate-700 p-3 text-sm"><p>{operationalText(reviewed.block?.data.reason,'Reason unavailable')}</p><p className="mt-1 text-slate-400">{date(reviewed.block?.data.startsAt,timeZone)} to {date(reviewed.block?.data.endsAt,timeZone)}</p></section>:<><p className="text-sm text-slate-400">Times use {timeZone}. The server checks current reservations, turnaround, other holds and maintenance before committing.</p><label className="block text-sm">Hold starts<input required type="datetime-local" className={`${field} mt-1`} data-business-timezone={timeZone} value={starts} disabled={locked} onChange={event=>setStarts(event.target.value)}/></label><label className="block text-sm">Hold ends<input required type="datetime-local" className={`${field} mt-1`} data-business-timezone={timeZone} value={ends} disabled={locked} onChange={event=>setEnds(event.target.value)}/></label></>}
   <label className="block text-sm">{release?'Inspection and release reason':'Reason for hold'}<textarea required minLength={3} maxLength={1000} className={`${field} mt-1`} value={note} disabled={locked} onChange={event=>setNote(event.target.value)}/></label>
   {blocker&&<p role="alert" className="text-sm text-amber-200">{blocker}</p>}{notice&&<p role="status" className="text-sm text-amber-200">{notice}</p>}{held&&<p role="status" className="text-sm text-amber-200">Original room update pending or its confirmed display is still updating. A new command is disabled.</p>}
   <div className="flex flex-wrap justify-end gap-2">{onActivity&&<button type="button" className={`${button} min-h-11`} disabled={busy} onClick={onActivity}>Open Activity</button>}<button type="button" className={`${button} min-h-11`} disabled={busy||held||disabled} onClick={()=>void refreshReview()}>Refresh and review</button><button type="button" className={`${button} min-h-11`} disabled={busy||held} onClick={onClose}>Close</button><button className={`${primary} min-h-11`} aria-busy={busy} disabled={locked||note.trim().length<3}>{busy?'Submitting...':release?'Confirm operating hold release':'Confirm operating hold'}</button></div>
  </form>
 </Dialog>;
}
